+  }
+  let total = 0;
+  for (const [, n, u] of s.matchAll(/(\d+(?:\.\d+)?)(ms|d|h|m|s)/g)) {
+    total += Number(n) * UNIT[u];
+  }
+  return Math.round(total);
 }

 export function formatDuration(ms: number): string {
-  throw new Error('not implemented');
+  if (!Number.isFinite(ms) || ms < 0) {
+    throw new Error(`invalid duration: ${ms}`);
+  }
+  let rest = Math.round(ms);
+  if (rest === 0) return '0s';
+  let out = '';
+  for (const u of ['d', 'h', 'm', 's', 'ms']) {
+    const n = Math.floor(rest / UNIT[u]);
+    if (n > 0) out += `${n}${u}`;
+    rest %= UNIT[u];
+  }
+  return out;
 }
